async function updateBuildInfo(){try{const t=await fetch("https://api.github.com/repos/infinotiver/infinotiver.github.io/commits"),e=await t.json(),n=e[0]?.sha.substring(0,7),o=e[0]?.commit.author.date;document.getElementById("last-commit").textContent=n||"N/A",document.getElementById("last-update").textContent=o||"N/A"}catch(t){console.error("Error fetching GitHub data:",t)}}updateBuildInfo();